package cn.codedog.controller;
import cn.codedog.service.*;import jakarta.servlet.http.HttpServletRequest;import org.springframework.web.bind.annotation.*;import java.security.Principal;import java.util.*;
@RestController public class RankingAftercareController {
 @org.springframework.beans.factory.annotation.Autowired private org.springframework.jdbc.core.JdbcTemplate jdbc;
 private final RankingAftercareService service;private final StudentRankingAuthService students;private final PermissionService permissions;private final AuditService audit;
 public RankingAftercareController(RankingAftercareService s,StudentRankingAuthService a,PermissionService p,AuditService l){service=s;students=a;permissions=p;audit=l;}
 @PostMapping("/api/public/rankings/student-redemptions/{id}/cancel-request") public Object request(@PathVariable long id,@RequestBody Note body,HttpServletRequest r){var s=students.current(r);service.requestCancellation(s.ownerUsername(),s.studentId(),id,body.reason());audit.change("REDEMPTION",id,Map.of("status","PENDING"),Map.of("status","CANCEL_REQUESTED","reason",body.reason()));audit.record("student_cancellation_requested",r);return Map.of("accepted",true);}
 @GetMapping("/api/rankings/admin/aftercare/cancellations") public Object cancellations(Principal p){return service.cancellations(p.getName(),permissions.isAdmin(p.getName()));}
 @PostMapping("/api/rankings/admin/aftercare/cancellations/{id}/decision") public Object decide(@PathVariable long id,@RequestBody Decision b,Principal p,HttpServletRequest r){String owner=p.getName();if(permissions.isAdmin(owner)){var rows=jdbc.queryForList("SELECT owner_username FROM ranking_reward_redemptions WHERE id=?",id);if(!rows.isEmpty())owner=(String)rows.getFirst().get("owner_username");}audit.owner(owner);var v=service.decide(owner,id,b.approved(),b.reason(),p.getName());audit.change("REDEMPTION",id,Map.of("status","CANCEL_REQUESTED"),v);audit.record("ranking_cancellation_decided",r);return v;}
 @PostMapping("/api/public/rankings/student-auth/recovery") public Object recovery(@RequestBody Recovery body,HttpServletRequest r){if(jdbc.queryForObject("SELECT COUNT(*) FROM audit_log WHERE event_code='student_recovery_requested' AND ip_address=? AND created_at>?",Integer.class,r.getRemoteAddr(),java.sql.Timestamp.from(java.time.Instant.now().minusSeconds(900)))<10)service.requestRecovery(body.phone(),body.studentId(),body.reason());audit.record("student_recovery_requested",r);return Map.of("message","申请已受理，请联系老师核实身份");}
 @GetMapping("/api/rankings/admin/aftercare/recoveries") public Object recoveries(Principal p){return service.recoveries(p.getName(),permissions.isAdmin(p.getName()));}
 @PostMapping("/api/rankings/admin/aftercare/recoveries/{id}/verify") public Object verify(@PathVariable long id,@RequestBody Decision b,Principal p,HttpServletRequest r){var v=service.verify(p.getName(),id,b.approved(),b.reason());audit.change("ACCOUNT_RECOVERY",id,Map.of("status","PENDING_VERIFY"),v);audit.record("student_recovery_verified",r);return v;}
 @PostMapping("/api/rankings/admin/aftercare/recoveries/{id}/resolve") public Object resolve(@PathVariable long id,@RequestBody Reset b,Principal p,HttpServletRequest r){var v=service.resolve(id,b.password(),p.getName());audit.owner((String)v.get("owner"));audit.change("ACCOUNT_RECOVERY",id,Map.of("status","VERIFIED"),Map.of("status","RESOLVED","credentialState","rotated"));audit.record("student_recovery_resolved",r);return v;}
 @GetMapping("/api/rankings/admin/aftercare/legacy-orders") public Object legacyOrders(Principal p){return service.legacyOrders(p.getName());}
 public record Note(String reason){}public record Decision(boolean approved,String reason){}public record Recovery(String phone,String studentId,String reason){}public record Reset(String password){}
}
